// Блог v4 (26.11.2026): 6 нових статей + дати публікації заднім числом; одноразово записуються в settings.site.posts
export const BLOG4 = [{"id": 6, "st": "pub", "img": "/assets/img/blog/fiksatory-fundamentna-plyta.webp", "tag": ["Будівництво", "Construction"], "date": "2025-08-12", "slug": {"uk": "fiksatory-dlia-fundamentnoi-plyty", "en": "rebar-spacers-for-raft-foundation"}, "t": ["Фіксатори арматури для фундаментної плити: вибір, схема розкладки та кількість", "Rebar spacers for raft foundations: choice, layout and quantity"], "e": ["Які фіксатори потрібні для фундаментної плити на піску, щебені чи плівці, як підібрати висоту під захисний шар фундаменту, як розкласти опори і скільки їх закласти на об’єкт.", "Which spacers suit a raft foundation on sand, gravel or membrane, how to match the height to the foundation cover, how to lay supports out and how many to order."], "b": [[["p", "Фундаментна плита — найнавантаженіша конструкція будинку, і водночас саме в ній найчастіше «з’їдають» захисний шар бетону. Арматурний каркас вагою в кілька тонн лежить на сипкій основі, по ньому ходять арматурники, тягнуть рукав бетононасоса, а потім ущільнюють суміш глибинним вібратором. Якщо нижня сітка опуститься до основи, сталь опиниться в зоні постійної вологи з ґрунту — і корозія почнеться значно раніше, ніж розраховував проєктувальник."], ["p", "У цій статті розбираємо, які фіксатори арматури підходять для фундаменту, як підібрати висоту під проєктний захисний шар, як правильно розкласти опори на піску, щебені чи гідроізоляції та скільки їх потрібно на плиту. Загальні принципи вибору ми описували в статті <a href=\"/blog/yak-obraty-fiksator-armatury\" data-go=\"post\" data-a=\"1\">«Як обрати фіксатор арматури»</a>, а тут — саме про фундамент."], ["h2", "Чому для фундаменту потрібен особливий фіксатор"], ["p", "Більшість фундаментних плит бетонують не на тверду основу, а на ущільнений пісок, щебеневу подушку, утеплювач або гідроізоляційну мембрану. Звичайна опора з малою площею під вагою каркаса просто тоне в такій основі, і захисний шар зменшується на кілька сантиметрів."], ["p", "Тому для фундаменту обирають фіксатори із широкою опорною площею. Вони розподіляють навантаження, не продавлюють основу й не прорізають плівку. Саме для цього створено <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">фіксатор «Настил»</a>."], ["blockquote", "<p>На сипкій основі важить не лише висота фіксатора, а й площа, якою він спирається. Опора, що «пішла» в пісок на 15 мм, — це мінус 15 мм захисного шару по всій плиті.</p>"], ["h2", "Який захисний шар потрібен фундаменту"], ["p", "Фундамент працює в найагресивніших умовах: постійний контакт із ґрунтом, волога, іноді — агресивні ґрунтові води. Тому захисний шар тут більший, ніж у перекриттях. Орієнтовно:"], ["ul", "<li>плита на бетонній підготовці — від 35–40 мм;</li><li>плита, яку бетонують безпосередньо на ґрунт або пісок, — від 70 мм;</li><li>верхня арматура плити — зазвичай 25–40 мм залежно від умов експлуатації.</li>"], ["p", "Точні значення завжди беруть із проєкту. Детальніше про те, від чого залежить товщина і чим загрожує її порушення, читайте в статті <a href=\"/blog/zakhysnyi-shar-betonu\" data-go=\"post\" data-a=\"2\">«Захисний шар бетону»</a>."], ["h2", "Як підібрати фіксатор під фундамент"], ["h3", "Нижня сітка на сипкій основі"], ["p", "Для нижньої арматури на піску, щебені чи плівці використовуйте «Настил». Його висоти — від 25–30 до 90–100 мм, тож можна закрити і стандартний шар на підготовці, і збільшений шар при бетонуванні на ґрунт. Обирайте висоту, що дорівнює проєктному захисному шару; якщо точного розміру немає — найближчу більшу."], ["h3", "Нижня сітка на бетонній підготовці"], ["p", "Якщо під плитою є шар підготовки з пісного бетону, основа вже тверда. Тут можна застосовувати <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійку»</a> — вона стабільно стоїть на рівній поверхні і має багаторівневі типорозміри. Для каркасів, по яких активно ходять, підійде <a href=\"/fiksator-zasuvka\" data-go=\"product\" data-a=\"5-0\">«Засувка»</a>: вона фіксується на стрижні й не зміщується."], ["h3", "Бічні грані плити й ростверку"], ["p", "Біля опалубки по периметру арматура має триматися на відстані від щитів. Для цього на крайні стрижні надягають <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочки»</a> — вони забезпечують однаковий шар з боку опалубки."], ["h3", "Верхня сітка"], ["p", "Фіксатори захисного шару тримають лише нижню арматуру. Верхню сітку фундаменту встановлюють на окремі підставки або каркаси, розраховані на висоту між сітками. Не намагайтеся замінити їх високими фіксаторами — вони не розраховані на таке навантаження."], ["cta", "{\"t\": \"Підберемо фіксатори під ваш фундамент\", \"d\": \"Надішліть креслення плити — порахуємо кількість «Настилу», «Стійок» і «Зірочок» та запропонуємо доставку на об’єкт.\", \"b\": [[\"Фіксатори арматури\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Схема розкладки фіксаторів на плиті"], ["ol", "<li>Розкладіть фіксатори рядами в шаховому порядку з кроком, що залежить від діаметра арматури: для стрижнів 10–12 мм — орієнтовно 0,6–0,8 м, для 14–20 мм — до 0,8–1 м.</li><li>Обов’язково поставте опори вздовж країв плити, біля отворів і в місцях нахлесту стрижнів.</li><li>Під місцями, де будуть ходити й котити тачки, крок зменшіть.</li><li>Після укладання сітки пройдіться по ній і перевірте, чи не прогинається вона між опорами.</li><li>Перед бетонуванням виміряйте відстань від арматури до основи в кількох точках по всій площі.</li>"], ["h2", "Скільки фіксаторів потрібно на фундаментну плиту"], ["p", "Орієнтовна витрата для нижньої сітки — 4–6 шт. на м². Для плити площею 100 м² це 400–600 фіксаторів «Настил». Додайте запас 5–10 % на втрати й підрізку. До цього числа додаються «Зірочки» для периметра — приблизно по одній на кожен метр бічної грані з кроком по висоті. Докладна методика є в статті <a href=\"/blog/yak-rozrakhuvaty-kilkist-fiksatoriv\" data-go=\"post\" data-a=\"9\">«Як розрахувати кількість фіксаторів»</a>."], ["p", "Фіксатори PLASTIZA постачаються упаковками від 100 до 2000 шт. — точне фасування вказане в картці кожного товару."], ["h2", "Типові помилки при армуванні фундаменту"], ["ul", "<li>Каркас кладуть на цеглу, щебінь чи бруски — висота довільна, а дерево й цегла вбирають вологу з ґрунту.</li><li>Використовують опори з малою площею на піску — вони тонуть під вагою каркаса.</li><li>Рвуть гідроізоляційну плівку гострими опорами, і вода з ґрунту отримує прямий шлях до бетону.</li><li>Ставлять фіксатори лише по периметру, а в центрі плити сітка лягає на основу.</li><li>Не перевіряють захисний шар перед бетонуванням.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна класти арматуру фундаменту на цеглу?"], ["p", "Не варто. Цегла має довільну висоту, вбирає воду й може розколотися під вагою каркаса. Пластикові фіксатори дають точну висоту й не створюють шляху для вологи до арматури."], ["h3", "Чи не продавить «Настил» утеплювач XPS?"], ["p", "«Настил» має збільшену площу опори саме для м’яких основ. Для утеплювачів із низькою міцністю на стиск зменшіть крок установки, щоб розподілити навантаження."], ["h3", "Які фіксатори потрібні для стрічкового фундаменту?"], ["p", "Для підошви стрічки — ті самі «Настил» або «Стійка» залежно від основи, а для бічних граней і вертикальних випусків — «Зірочки»."], ["h2", "Висновок"], ["p", "Для фундаментної плити на сипкій основі обирайте «Настил» з висотою, що дорівнює проєктному захисному шару, на підготовці — «Стійку» або «Засувку», по периметру — «Зірочки». Розкладайте опори в шаховому порядку з кроком 0,6–1 м і перевіряйте каркас перед заливанням. Надішліть нам креслення — і ми підберемо фіксатори та відвантажимо їх зі складу у Львові чи Києві."]], [["p", "A raft foundation is the most heavily loaded element of a building — and the one where concrete cover is lost most often. A cage weighing several tonnes rests on a loose base, workers walk on it, the pump hose is dragged across it and a poker vibrator compacts the mix. If the bottom mesh sinks to the base, the steel ends up in constant ground moisture and corrosion starts far earlier than the designer assumed."], ["p", "This article explains which rebar spacers suit foundations, how to match the height to the design cover, how to lay supports out on sand, gravel or waterproofing and how many you need. General selection rules are in <a href=\"/en/blog/how-to-choose-rebar-spacer\" data-go=\"post\" data-a=\"1\">“How to choose a rebar spacer”</a>; here we focus on foundations."], ["h2", "Why foundations need a special spacer"], ["p", "Most rafts are cast not on a firm base but on compacted sand, a gravel bed, insulation or a waterproofing membrane. An ordinary support with a small footprint sinks into such a base under the cage, and the cover shrinks by centimetres."], ["p", "Foundations therefore need spacers with a wide footprint that spread the load, do not punch into the base and do not cut the membrane. That is what the <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil” slab chair</a> is for."], ["blockquote", "<p>On a loose base, footprint matters as much as height. A support that sinks 15 mm into sand means 15 mm less cover across the whole slab.</p>"], ["h2", "What cover a foundation needs"], ["p", "Foundations work in the harshest conditions: permanent soil contact, moisture and sometimes aggressive groundwater. Cover is therefore larger than in floor slabs. As a guide:"], ["ul", "<li>raft on concrete blinding — from 35–40 mm;</li><li>raft cast directly on soil or sand — from 70 mm;</li><li>top reinforcement — usually 25–40 mm depending on exposure.</li>"], ["p", "Always take the exact values from the design. See <a href=\"/en/blog/concrete-cover\" data-go=\"post\" data-a=\"2\">“Concrete cover”</a> for what determines thickness and what goes wrong when it is not achieved."], ["h2", "Choosing a spacer for the foundation"], ["h3", "Bottom mesh on a loose base"], ["p", "Use “Nastil” for bottom rebar on sand, gravel or membrane. Heights range from 25–30 to 90–100 mm, covering both standard cover on blinding and increased cover when casting on soil. Choose the height equal to the design cover; if it is unavailable, go one size up."], ["h3", "Bottom mesh on blinding"], ["p", "If the raft sits on lean-concrete blinding, the base is firm. <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> stands stably on a flat surface and has multi-level sizes. For cages with heavy foot traffic, <a href=\"/en/slide-spacer-zasuvka\" data-go=\"product\" data-a=\"5-0\">“Zasuvka”</a> clips onto the bar and does not move."], ["h3", "Raft and pile-cap edges"], ["p", "Next to perimeter formwork, rebar must stay clear of the panels. Fit <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka” wheel spacers</a> on the edge bars to keep cover equal on the formwork side."], ["h3", "Top mesh"], ["p", "Cover spacers only carry the bottom reinforcement. The top mesh sits on separate chairs sized to the distance between meshes — do not replace them with tall cover spacers."], ["cta", "{\"t\": \"Spacers for your foundation\", \"d\": \"Send the slab drawing — we will calculate “Nastil”, “Stiika” and “Zirochka” quantities and offer delivery to site.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Spacer layout on a raft"], ["ol", "<li>Lay spacers in staggered rows at a spacing set by bar diameter: about 0.6–0.8 m for 10–12 mm bars, up to 0.8–1 m for 14–20 mm.</li><li>Always add supports along slab edges, around openings and at bar laps.</li><li>Reduce spacing where people will walk and barrows will run.</li><li>Walk the mesh after laying and check it does not sag between supports.</li><li>Before the pour, measure the distance from rebar to base at several points across the slab.</li>"], ["h2", "How many spacers a raft needs"], ["p", "Allow roughly 4–6 pcs per m² for the bottom mesh: 400–600 “Nastil” spacers for a 100 m² raft, plus 5–10 % reserve. Add “Zirochka” spacers for the perimeter — about one per metre of edge per level. See <a href=\"/en/blog/how-to-calculate-rebar-spacers\" data-go=\"post\" data-a=\"9\">“How to calculate rebar spacers”</a> for the full method."], ["p", "PLASTIZA spacers come in packs of 100 to 2,000 pcs — the exact pack size is on each product page."], ["h2", "Common mistakes"], ["ul", "<li>Laying the cage on brick, gravel or timber — random height, and brick and timber absorb ground moisture.</li><li>Using small-footprint supports on sand — they sink under the cage.</li><li>Tearing the membrane with sharp supports, giving groundwater a direct path to the concrete.</li><li>Placing spacers only around the edge, so the centre of the mesh rests on the base.</li><li>Skipping the cover check before pouring.</li>"], ["h2", "FAQ"], ["h3", "Can foundation rebar sit on bricks?"], ["p", "Better not. Brick gives a random height, absorbs water and can crack under the cage. Plastic spacers give an exact height and no moisture path to the steel."], ["h3", "Will “Nastil” punch into XPS insulation?"], ["p", "“Nastil” has an enlarged footprint for soft bases. On low-strength insulation, reduce the spacing to spread the load."], ["h3", "Which spacers suit a strip foundation?"], ["p", "“Nastil” or “Stiika” for the footing depending on the base, and “Zirochka” for side faces and vertical starter bars."], ["h2", "Conclusion"], ["p", "On a loose base use “Nastil” at the design cover height, on blinding use “Stiika” or “Zasuvka”, and “Zirochka” around the perimeter. Lay supports staggered at 0.6–1 m and check the cage before pouring. Send us your drawing and we will pick the spacers and ship them from Lviv or Kyiv."]]]}, {"id": 7, "st": "pub", "img": "/assets/img/blog/armuvannia-perekryttia.webp", "tag": ["Будівництво", "Construction"], "date": "2025-10-21", "slug": {"uk": "armuvannia-monolitnoho-perekryttia", "en": "floor-slab-reinforcement-cover"}, "t": ["Армування монолітного перекриття: як витримати захисний шар і не зіпсувати каркас", "Reinforcing a cast-in-place floor slab: keeping concrete cover and protecting the cage"], "e": ["Як забезпечити проєктний захисний шар у плиті перекриття: які фіксатори обрати для нижньої сітки на опалубці, як закріпити каркас і чого уникати під час бетонування.", "How to achieve design cover in a floor slab: which spacers to use for the bottom mesh on formwork, how to secure the cage and what to avoid during the pour."], "b": [[["p", "Монолітне перекриття — це тонка плита, в якій кожен міліметр має значення. Товщина перекриття зазвичай 160–220 мм, а захисний шар нижньої арматури — лише 15–25 мм. Якщо сітка опуститься до опалубки, після розпалублення на стелі проступлять іржаві смуги, а вогнестійкість перекриття знизиться. Якщо ж сітка підніметься вище проєкту, зменшиться робоча висота перерізу й несна здатність плити."], ["p", "У цій статті розповідаємо, які фіксатори арматури використовують для перекриттів, як їх розставляти на опалубці та як зберегти каркас під час бетонування."], ["h2", "Особливості захисного шару в перекриттях"], ["p", "Нижня арматура перекриття працює на розтяг і найбільше впливає на несну здатність. Захисний шар тут відносно тонкий: для внутрішніх приміщень — орієнтовно 15–25 мм, для вологих приміщень і перекриттів над паркінгами — більше. Значення для вашого об’єкта беруть із проєкту."], ["p", "Тонкий шар має дві вразливості:"], ["ul", "<li>його легко «з’їсти» — достатньо сітці прогнутися між опорами на 5–10 мм;</li><li>будь-який дефект видно на стелі — іржаві плями, тріщини вздовж стрижнів, відшарування.</li>"], ["blockquote", "<p>У перекритті немає запасу. Якщо фундамент може пробачити кілька міліметрів, то тонка плита одразу покаже помилку на стелі.</p>"], ["h2", "Які фіксатори використовувати для перекриття"], ["p", "Нижня сітка перекриття лежить на опалубці — фанері або щитах, тобто на твердій рівній основі. Тут підходять такі вироби:"], ["h3", "«Стійка»"], ["p", "<a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">Фіксатор «Стійка»</a> — основний вибір для перекриттів. Він стабільно стоїть на опалубці, рівномірно розподіляє вагу сітки, а багаторівневі моделі (наприклад, 20-25-30) дають кілька висот в одному виробі."], ["h3", "«Защіпка»"], ["p", "<a href=\"/fiksator-zashchipka\" data-go=\"product\" data-a=\"4-0\">«Защіпка»</a> защіпається на стрижень і утримує його на заданій висоті — 15, 20 або 25 мм. Вона зручна для тонких захисних шарів і не дає фіксатору випасти під час ходіння по сітці."], ["h3", "«Засувка»"], ["p", "<a href=\"/fiksator-zasuvka\" data-go=\"product\" data-a=\"5-0\">«Засувка»</a> розрахована на більші навантаження й діаметри арматури — до 24 мм. Її використовують у зонах із густим армуванням, біля капітелей і над опорами."], ["h3", "«Зірочка» по торцях"], ["p", "По торцях плити, біля бортової опалубки й отворів, на крайні стрижні надягають <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочки»</a>, щоб витримати шар і з боку щита."], ["cta", "{\"t\": \"Комплект фіксаторів для перекриття\", \"d\": \"Порахуємо «Стійки», «Защіпки» та «Зірочки» під площу й армування вашої плити.\", \"b\": [[\"Фіксатори арматури\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Як розставити фіксатори на опалубці"], ["ol", "<li>Візьміть із креслень захисний шар нижньої арматури й підберіть фіксатор точно під нього.</li><li>Розставте опори в шаховому порядку з кроком близько 0,6–0,8 м для стрижнів 8–12 мм.</li><li>Додайте фіксатори вздовж бортів, біля отворів, під місцями нахлесту й зонами додаткового армування.</li><li>Верхню сітку встановлюйте на окремі підставки — фіксатори захисного шару для неї не призначені.</li><li>Перед бетонуванням пройдіться по каркасу й перевірте відстань до опалубки в кількох точках.</li>"], ["h2", "Як зберегти каркас під час бетонування"], ["ul", "<li>Прокладайте містки або трапи для руху по арматурі, особливо там, де катають тачки.</li><li>Не кидайте бетон з висоти в одне місце — подавайте рівномірно, щоб не продавити сітку.</li><li>Не впирайте глибинний вібратор у фіксатори й арматуру.</li><li>Тримайте запас фіксаторів на майданчику, щоб одразу замінити пошкоджені.</li>"], ["h2", "Скільки фіксаторів потрібно на перекриття"], ["p", "Орієнтовно 4–6 шт. на м² для нижньої сітки. Для перекриття площею 150 м² це 600–900 фіксаторів плюс 5–10 % запасу. Тонкі стрижні (8–10 мм) вимагають частішого кроку, ніж 12–16 мм. Детальніше — у статті <a href=\"/blog/yak-rozrakhuvaty-kilkist-fiksatoriv\" data-go=\"post\" data-a=\"9\">«Як розрахувати кількість фіксаторів»</a>, а про загальні принципи вибору — в статті <a href=\"/blog/yak-obraty-fiksator-armatury\" data-go=\"post\" data-a=\"1\">«Як обрати фіксатор арматури»</a>."], ["h2", "Типові помилки"], ["ul", "<li>Фіксатори ставлять лише по периметру, і в центрі прольоту сітка лягає на опалубку.</li><li>Беруть фіксатор «трохи нижчий», бо потрібного немає на майданчику.</li><li>Використовують металеві підставки без захисту — їхні сліди потім іржавіють на стелі.</li><li>Не закріплюють сітку, і вона зсувається під час подачі бетону.</li>"], ["h2", "Часті питання"], ["h3", "Чи видно пластикові фіксатори на стелі після розпалублення?"], ["p", "На поверхні можуть залишатися невеликі сліди опор, але пластик не іржавіє, тож вони не змінюють колір із часом і легко зникають під штукатуркою чи шпаклівкою."], ["h3", "Яку висоту фіксатора брати для перекриття 200 мм?"], ["p", "Висота фіксатора залежить не від товщини плити, а від проєктного захисного шару — зазвичай 15–25 мм для нижньої арматури. Точне значення дивіться в кресленнях."], ["h3", "Чи можна використовувати «Настил» на опалубці?"], ["p", "Можна, але немає потреби: «Настил» розрахований на сипкі основи. Для опалубки економніше й зручніше використовувати «Стійку» або «Защіпку»."], ["h2", "Висновок"], ["p", "Для монолітного перекриття ключове — точна висота фіксатора під тонкий захисний шар, достатня кількість опор і акуратне бетонування. «Стійка» й «Защіпка» тримають нижню сітку, «Засувка» — густе армування, «Зірочка» — торці. Залиште заявку нижче — підберемо комплект фіксаторів під ваше перекриття."]], [["p", "A cast-in-place floor slab is thin, and every millimetre counts. Slabs are typically 160–220 mm thick, with only 15–25 mm cover to the bottom rebar. If the mesh drops onto the formwork, rust lines appear on the ceiling after stripping and fire resistance falls. If it rises above the design level, the effective depth and load capacity decrease."], ["p", "This article covers which rebar spacers to use in floor slabs, how to place them on formwork and how to protect the cage during the pour."], ["h2", "Concrete cover in floor slabs"], ["p", "The bottom rebar works in tension and drives load capacity. Cover is relatively thin: about 15–25 mm for interior slabs, more for wet areas and slabs over car parks. Take the exact value from the design."], ["p", "Thin cover has two weaknesses:"], ["ul", "<li>it is easy to lose — a 5–10 mm sag between supports is enough;</li><li>any defect shows on the ceiling — rust stains, cracks along bars, spalling.</li>"], ["blockquote", "<p>A slab has no margin. A foundation may forgive a few millimetres; a thin slab shows the mistake on the ceiling.</p>"], ["h2", "Which spacers to use"], ["p", "The bottom mesh rests on plywood or panel formwork — a firm, flat base. Suitable products:"], ["h3", "“Stiika”"], ["p", "The <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika” chair</a> is the main choice for slabs. It stands firmly on formwork, spreads the weight of the mesh, and multi-level models (such as 20-25-30) give several heights in one part."], ["h3", "“Zashchipka”"], ["p", "<a href=\"/en/clip-spacer-zashchipka\" data-go=\"product\" data-a=\"4-0\">“Zashchipka”</a> clips onto the bar and holds it at 15, 20 or 25 mm. It suits thin cover and does not fall out when people walk on the mesh."], ["h3", "“Zasuvka”"], ["p", "<a href=\"/en/slide-spacer-zasuvka\" data-go=\"product\" data-a=\"5-0\">“Zasuvka”</a> is designed for heavier loads and bars up to 24 mm — used in congested zones, at column heads and over supports."], ["h3", "“Zirochka” at edges"], ["p", "At slab edges, edge formwork and openings, fit <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka” wheel spacers</a> on the outer bars to keep cover on the panel side."], ["cta", "{\"t\": \"A spacer set for your slab\", \"d\": \"We will calculate “Stiika”, “Zashchipka” and “Zirochka” quantities for your slab area and reinforcement.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Placing spacers on formwork"], ["ol", "<li>Take the bottom cover from the drawings and choose a spacer exactly to it.</li><li>Place supports staggered at about 0.6–0.8 m for 8–12 mm bars.</li><li>Add spacers along edges, around openings, under laps and in additional-reinforcement zones.</li><li>Support the top mesh on separate chairs — cover spacers are not meant for it.</li><li>Walk the cage before pouring and check the distance to formwork at several points.</li>"], ["h2", "Protecting the cage during the pour"], ["ul", "<li>Lay walkways or boards over the rebar, especially along barrow routes.</li><li>Do not drop concrete from height in one spot — place it evenly.</li><li>Keep the poker vibrator away from spacers and bars.</li><li>Keep spare spacers on site to replace damaged ones immediately.</li>"], ["h2", "How many spacers a slab needs"], ["p", "About 4–6 pcs per m² for the bottom mesh: 600–900 spacers for a 150 m² slab plus 5–10 % reserve. Thin bars (8–10 mm) need closer spacing than 12–16 mm. See <a href=\"/en/blog/how-to-calculate-rebar-spacers\" data-go=\"post\" data-a=\"9\">“How to calculate rebar spacers”</a> and <a href=\"/en/blog/how-to-choose-rebar-spacer\" data-go=\"post\" data-a=\"1\">“How to choose a rebar spacer”</a>."], ["h2", "Common mistakes"], ["ul", "<li>Placing spacers only along the perimeter, so the mesh rests on formwork mid-span.</li><li>Using a slightly lower spacer because the right one is not on site.</li><li>Using bare metal chairs whose marks later rust on the ceiling.</li><li>Not securing the mesh, so it shifts during the pour.</li>"], ["h2", "FAQ"], ["h3", "Are plastic spacers visible on the ceiling?"], ["p", "Small marks may remain, but plastic does not rust, so they do not stain over time and disappear under plaster or filler."], ["h3", "What spacer height for a 200 mm slab?"], ["p", "Height depends on the design cover, not slab thickness — usually 15–25 mm for bottom rebar. Check the drawings."], ["h3", "Can I use “Nastil” on formwork?"], ["p", "You can, but there is no need: “Nastil” is designed for loose bases. “Stiika” or “Zashchipka” are cheaper and easier on formwork."], ["h2", "Conclusion"], ["p", "In a floor slab, what matters is exact spacer height for thin cover, enough supports and a careful pour. “Stiika” and “Zashchipka” carry the bottom mesh, “Zasuvka” handles congested zones and “Zirochka” the edges. Leave a request below and we will put together a spacer set for your slab."]]]}, {"id": 8, "st": "pub", "img": "/assets/img/blog/fiksator-zirochka-stiny.webp", "tag": ["Поради", "Guides"], "date": "2025-11-25", "slug": {"uk": "fiksator-zirochka-dlia-stin-i-kolon", "en": "zirochka-wheel-spacer-walls-columns"}, "t": ["Фіксатор «Зірочка» для стін і колон: розміри, монтаж і крок установки", "“Zirochka” wheel spacer for walls and columns: sizes, installation and spacing"], "e": ["Як працює фіксатор «Зірочка», як підібрати розмір під захисний шар і діаметр арматури, як правильно встановити його на стінах і колонах і скільки штук потрібно.", "How the “Zirochka” wheel spacer works, how to choose its size for cover and bar diameter, how to fit it on walls and columns and how many you need."], "b": [[["p", "Стіни, колони й пілони бетонують у вертикальній опалубці, і тут фіксатори працюють інакше, ніж у плитах. Арматурний каркас треба втримати на однаковій відстані від щитів з обох боків, а під час монтажу опалубки нічого не повинно чіплятися й зсуватися. Для цього використовують кільцеві фіксатори — у нашому асортименті це <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">фіксатор «Зірочка»</a>."], ["p", "У статті розповідаємо, як влаштована «Зірочка», як підібрати її розмір, як правильно встановити й скільки штук закласти на стіну чи колону."], ["h2", "Як працює фіксатор «Зірочка»"], ["p", "«Зірочка» — це кільце з променями, яке надягається на вертикальний або горизонтальний стрижень. Його зовнішній край впирається в щит опалубки по колу, тому захисний шар однаковий незалежно від того, як повернувся фіксатор. Під час закриття опалубки «колесо» прокочується по щиту, а не чіпляється за нього."], ["p", "Еластичний замок у центрі охоплює стрижні різних діаметрів у межах типорозміру й тримається на арматурі без в’язального дроту."], ["blockquote", "<p>Перевага кільцевого фіксатора в тому, що він дає однаковий шар у будь-якому положенні: його не треба орієнтувати, він просто котиться разом зі щитом.</p>"], ["h2", "Розміри «Зірочки» і як їх читати"], ["p", "Позначення розміру складається з двох частин: перше число — захисний шар у міліметрах, далі — діапазон діаметрів арматури. Наприклад, 25/6-12 означає шар 25 мм для стрижнів від 6 до 12 мм. У нашому асортименті:"], ["ul", "<li>15/6-12 — для тонких стін і перегородок;</li><li>25/6-12 і 25/4-20 — найпоширеніші розміри для стін і колон;</li><li>30/8-20 і 35/6-12 — для збільшеного захисного шару;</li><li>40/14-20 і 50/12-20 — для фундаментних стін, ростверків і масивних конструкцій.</li>"], ["p", "Щоб обрати розмір, візьміть із проєкту захисний шар і діаметр стрижня, на який буде встановлено фіксатор. Пам’ятайте: шар відраховують до найближчого стрижня — часто це горизонтальна арматура або хомути, а не вертикальні стрижні."], ["h2", "Як правильно встановити «Зірочку»"], ["ol", "<li>Встановлюйте фіксатори після в’язання каркаса, але до монтажу другого щита опалубки.</li><li>Надягайте «Зірочку» на стрижень, найближчий до щита, так щоб площина кільця була перпендикулярна до опалубки.</li><li>На стінах розташовуйте фіксатори в шаховому порядку з обох боків каркаса.</li><li>На колонах ставте фіксатори на кожну грань — щонайменше по одному на грань у кожному ярусі.</li><li>Біля кутів, отворів, закладних деталей і в місцях стиків каркаса додайте фіксатори.</li>"], ["cta", "{\"t\": \"Потрібні «Зірочки» на стіни чи колони?\", \"d\": \"Підберемо розміри під ваш захисний шар і діаметри, порахуємо кількість і відвантажимо зі складу.\", \"b\": [[\"Фіксатор «Зірочка»\", \"p3\", \"product\", \"3-0\", \"/fiksator-zirochka\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Крок установки й кількість"], ["p", "Орієнтовний крок — близько 1 м по висоті й довжині стіни з кожного боку, у шаховому порядку. Для тонкої арматури й високих стін крок зменшують до 0,6–0,8 м. Отже, на 1 м² стіни припадає приблизно 1–2 фіксатори з кожного боку."], ["p", "Приклад: стіна завдовжки 10 м і заввишки 3 м має площу 30 м² з кожного боку. При кроці 1 м це близько 30–40 фіксаторів на сторону, тобто 60–80 на стіну, плюс 10 % запасу. Для колони перерізом 400×400 мм і висотою 3 м — по 3–4 фіксатори на кожну грань, разом 12–16 шт."], ["p", "Детальну методику розрахунку для всього об’єкта ми розібрали в статті <a href=\"/blog/yak-rozrakhuvaty-kilkist-fiksatoriv\" data-go=\"post\" data-a=\"9\">«Як розрахувати кількість фіксаторів»</a>."], ["h2", "«Зірочка» в горизонтальних конструкціях"], ["p", "Кільцеві фіксатори використовують не лише на вертикальних каркасах. Їх ставлять на крайні стрижні плит і балок біля бортової опалубки, на арматуру ростверків і на бічні грані фундаментних плит. А для нижньої сітки плит краще підходять опорні фіксатори — <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійка»</a> або <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a>."], ["h2", "Типові помилки"], ["ul", "<li>«Зірочку» обирають не під той діаметр — вона сповзає зі стрижня або не надягається.</li><li>Фіксатори ставлять лише з одного боку стіни.</li><li>Встановлюють на вертикальний стрижень, хоча ближче до щита розташована горизонтальна арматура — і шар виходить меншим.</li><li>Не додають фіксатори біля отворів і кутів.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна використовувати «Зірочку» на горизонтальній арматурі?"], ["p", "Так. Її ставлять на крайні стрижні плит і балок біля бортової опалубки, а також на горизонтальні стрижні стін."], ["h3", "Чи не зламається «Зірочка» під час монтажу опалубки?"], ["p", "Кільце прокочується по щиту й розраховане на такі навантаження. Важливо не тягнути щит уздовж каркаса з великим зусиллям."], ["h3", "Скільки «Зірочок» в упаковці?"], ["p", "Залежно від розміру — від кількох сотень до тисяч штук. Точне фасування вказане в картці товару."], ["h2", "Висновок"], ["p", "«Зірочка» — основний фіксатор для стін, колон і пілонів: вона дає однаковий захисний шар з усіх боків і не чіпляється за опалубку. Підберіть розмір за проєктним шаром і діаметром стрижня, ставте фіксатори в шаховому порядку з кроком близько 1 м і не забувайте про кути й отвори. Залиште заявку — і ми підготуємо розрахунок."]], [["p", "Walls, columns and piers are cast in vertical formwork, and spacers work differently here than in slabs. The cage must stay at equal distance from the panels on both sides, and nothing should snag or shift while the formwork is closed. That is the job of wheel spacers — in our range, the <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka” spacer</a>."], ["p", "This article explains how “Zirochka” works, how to choose its size, how to install it and how many to order for a wall or column."], ["h2", "How “Zirochka” works"], ["p", "“Zirochka” is a ring with spokes that clips onto a vertical or horizontal bar. Its outer rim bears against the formwork all around, so cover stays equal however the spacer turns. When the panel is closed, the wheel rolls along it instead of catching."], ["p", "A flexible lock in the centre grips bars of different diameters within its size range and holds without tie wire."], ["blockquote", "<p>A wheel spacer gives the same cover in any position: no orientation needed — it simply rolls with the panel.</p>"], ["h2", "Sizes and how to read them"], ["p", "The size has two parts: the first number is cover in millimetres, followed by the bar diameter range. For example, 25/6-12 means 25 mm cover for 6–12 mm bars. Our range includes:"], ["ul", "<li>15/6-12 — thin walls and partitions;</li><li>25/6-12 and 25/4-20 — the most common sizes for walls and columns;</li><li>30/8-20 and 35/6-12 — increased cover;</li><li>40/14-20 and 50/12-20 — basement walls, pile caps and massive elements.</li>"], ["p", "Choose by the design cover and the diameter of the bar the spacer sits on. Remember that cover is measured to the nearest bar — often horizontal bars or links rather than vertical bars."], ["h2", "How to install “Zirochka”"], ["ol", "<li>Fit spacers after the cage is tied but before the second formwork panel is closed.</li><li>Clip each spacer onto the bar nearest the panel, with the ring perpendicular to the formwork.</li><li>On walls, place spacers in a staggered pattern on both faces.</li><li>On columns, fit at least one spacer per face at each level.</li><li>Add spacers at corners, openings, embedded items and cage joints.</li>"], ["cta", "{\"t\": \"Need “Zirochka” spacers for walls or columns?\", \"d\": \"We will choose sizes for your cover and bar diameters, calculate quantities and ship from stock.\", \"b\": [[\"“Zirochka” spacer\", \"p3\", \"product\", \"3-0\", \"/en/star-spacer-zirochka\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Spacing and quantity"], ["p", "A typical spacing is about 1 m vertically and horizontally on each face, staggered. For thin bars and tall walls reduce it to 0.6–0.8 m. That gives roughly 1–2 spacers per m² per face."], ["p", "Example: a wall 10 m long and 3 m high has 30 m² per face. At 1 m spacing that is about 30–40 spacers per face, 60–80 per wall, plus 10 % reserve. A 400×400 mm column 3 m high needs 3–4 spacers per face — 12–16 in total."], ["p", "See <a href=\"/en/blog/how-to-calculate-rebar-spacers\" data-go=\"post\" data-a=\"9\">“How to calculate rebar spacers”</a> for a whole-project method."], ["h2", "“Zirochka” in horizontal elements"], ["p", "Wheel spacers are not only for vertical cages. They go on the edge bars of slabs and beams next to edge formwork, on pile-cap reinforcement and on raft side faces. For the bottom mesh of slabs, use chairs — <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> or <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a>."], ["h2", "Common mistakes"], ["ul", "<li>Choosing a size for the wrong diameter — it slides off or will not fit.</li><li>Fitting spacers on one face of the wall only.</li><li>Fitting on vertical bars when horizontal bars are closer to the panel — so cover comes out smaller.</li><li>Skipping spacers at openings and corners.</li>"], ["h2", "FAQ"], ["h3", "Can “Zirochka” go on horizontal bars?"], ["p", "Yes — on the outer bars of slabs and beams next to edge formwork, and on the horizontal bars of walls."], ["h3", "Will it break when the formwork is closed?"], ["p", "The ring rolls along the panel and is designed for this. Just avoid dragging the panel along the cage with excessive force."], ["h3", "How many come in a pack?"], ["p", "Depending on size, from several hundred to several thousand. The exact pack is on the product page."], ["h2", "Conclusion"], ["p", "“Zirochka” is the main spacer for walls, columns and piers: it gives equal cover on all sides and does not snag the formwork. Choose the size by design cover and bar diameter, place spacers staggered at about 1 m and remember corners and openings. Leave a request and we will prepare a quote."]]]}, {"id": 9, "st": "pub", "img": "/assets/img/blog/rozrakhunok-fiksatoriv.webp", "tag": ["Поради", "Guides"], "date": "2026-01-20", "slug": {"uk": "yak-rozrakhuvaty-kilkist-fiksatoriv", "en": "how-to-calculate-rebar-spacers"}, "t": ["Як розрахувати кількість фіксаторів арматури на об’єкт: формули та приклади", "How to calculate the number of rebar spacers for a project: formulas and examples"], "e": ["Покрокова методика розрахунку фіксаторів арматури для плит, фундаментів, стін і колон: витрата на м², крок установки, запас і приклад розрахунку для приватного будинку.", "A step-by-step method for calculating rebar spacers for slabs, foundations, walls and columns: consumption per m², spacing, reserve and a worked example for a private house."], "b": [[["p", "Фіксатори арматури коштують недорого, але їхня нестача на майданчику коштує дорого: бригада простоює, каркас кладуть на цеглу, а захисний шар порушується. Надлишок — теж зайві гроші й залишки на складі. Тому кількість фіксаторів краще порахувати заздалегідь, разом із кошторисом на арматуру й бетон."], ["p", "У цій статті даємо просту методику розрахунку фіксаторів для різних конструкцій і приклад для приватного будинку. Тип фіксатора під кожну конструкцію ми розбирали в статті <a href=\"/blog/yak-obraty-fiksator-armatury\" data-go=\"post\" data-a=\"1\">«Як обрати фіксатор арматури»</a>."], ["h2", "Від чого залежить кількість фіксаторів"], ["ul", "<li><b>Тип конструкції:</b> плити, фундаменти, стіни, колони, балки.</li><li><b>Діаметр і крок арматури:</b> тонкі стрижні прогинаються між опорами, тому потребують частішого кроку.</li><li><b>Навантаження під час робіт:</b> ходіння, тачки, рукав бетононасоса.</li><li><b>Основа:</b> на сипкій основі опори ставлять частіше.</li><li><b>Конфігурація:</b> кути, отвори, нахлести й зони додаткового армування потребують додаткових фіксаторів.</li>"], ["h2", "Базові норми витрати"], ["p", "Ці значення — практичний орієнтир, на який спираються більшість будівельників:"], ["ul", "<li>плити перекриття та фундаментні плити (нижня сітка) — 4–6 шт. на м²;</li><li>стіни й пілони — 1–2 шт. на м² з кожного боку стіни;</li><li>колони — 3–4 фіксатори на кожну грань на кожні 3 м висоти;</li><li>балки й ригелі — фіксатор знизу кожні 0,8–1 м плюс бічні «Зірочки».</li>"], ["blockquote", "<p>Норма на м² — це середнє значення. Остаточну кількість завжди коригують під діаметр арматури й конфігурацію конструкції.</p>"], ["h2", "Формули розрахунку"], ["h3", "Плити й фундаменти"], ["p", "Кількість = площа плити (м²) × норма (шт./м²) × 1,1"], ["p", "Множник 1,1 — запас 10 % на втрати, підрізку й додаткові опори біля отворів."], ["h3", "Стіни"], ["p", "Кількість = площа стіни (м²) × 2 сторони × норма (шт./м²) × 1,1"], ["h3", "Колони"], ["p", "Кількість = кількість граней × кількість ярусів по висоті × кількість колон × 1,1"], ["h3", "Через крок установки"], ["p", "Якщо в проєкті вказано крок фіксаторів, рахуйте точніше: кількість = (довжина / крок + 1) × (ширина / крок + 1)."], ["h2", "Приклад розрахунку для приватного будинку"], ["p", "Будинок із фундаментною плитою 12×10 м, монолітними стінами підвалу і перекриттям:"], ["ol", "<li><b>Фундаментна плита 120 м²</b>, норма 5 шт./м²: 120 × 5 × 1,1 = 660 фіксаторів <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a>.</li><li><b>Стіни підвалу:</b> периметр 44 м, висота 2,7 м — площа 119 м². З двох боків при нормі 1,5 шт./м²: 119 × 2 × 1,5 × 1,1 ≈ 393 <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочки»</a>.</li><li><b>Перекриття 110 м²</b>, норма 5 шт./м²: 110 × 5 × 1,1 = 605 <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійок»</a>.</li><li><b>Торці плит:</b> периметр плити й перекриття — по 44 м, з кроком 1 м — близько 90 «Зірочок».</li>"], ["p", "Разом: 660 «Настилів», 605 «Стійок» і близько 480 «Зірочок». Фіксатори постачаються упаковками, тому результат округлюють до цілих упаковок — точне фасування є в картці кожного товару."], ["cta", "{\"t\": \"Порахуємо фіксатори за вашим проєктом\", \"d\": \"Надішліть креслення або специфікацію — підготуємо точний розрахунок за типами й розмірами та ціну з доставкою.\", \"b\": [[\"Каталог фіксаторів\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Розрахунок елементів для опалубки"], ["p", "Якщо стіни бетонують у щитовій опалубці зі стяжними гвинтами, окремо рахують:"], ["ul", "<li><a href=\"/dystantsiina-truba\" data-go=\"product\" data-a=\"9-0\">дистанційну трубу</a> — у метрах: кількість точок стяжки × товщина стіни;</li><li><a href=\"/fiksator-konus\" data-go=\"product\" data-a=\"6-0\">конуси</a> — по два на кожну точку стяжки;</li><li><a href=\"/fiksator-korok\" data-go=\"product\" data-a=\"8-0\">корки</a> — по два на кожну точку, плюс <a href=\"/korok-yalynka\" data-go=\"product\" data-a=\"7-0\">корки-ялинки</a> для невикористаних отворів щитів.</li>"], ["p", "Як працює кожен елемент, ми пояснили в статті <a href=\"/blog/korky-i-konusy-dlia-opalubky\" data-go=\"post\" data-a=\"5\">«Конуси, корки й дистанційні труби для опалубки»</a>."], ["h2", "Типові помилки в розрахунку"], ["ul", "<li>Рахують лише площу плит і забувають про стіни, колони й торці.</li><li>Не закладають запас — і докуповують фіксатори вже під час робіт.</li><li>Беруть одну висоту на весь об’єкт, хоча захисний шар фундаменту й перекриття різний.</li><li>Не враховують, що труба для опалубки продається метрами, а не штуками.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна порахувати фіксатори без креслень?"], ["p", "Орієнтовно — так, за площею плит і стін за нормами вище. Але для точної специфікації за розмірами краще мати креслення."], ["h3", "Скільки фіксаторів потрібно на 1 м² плити?"], ["p", "У середньому 4–6 шт. для нижньої сітки — менше для товстої арматури, більше для тонкої."], ["h3", "Ви можете зробити розрахунок за нас?"], ["p", "Так. Надішліть креслення або кошторис — менеджер підготує специфікацію з типами, розмірами й кількістю фіксаторів."], ["h2", "Висновок"], ["p", "Кількість фіксаторів рахують за площею конструкцій і нормою витрати з урахуванням діаметра арматури та запасу 10 %. Для плит — 4–6 шт./м², для стін — 1–2 шт./м² з кожного боку, для колон — 3–4 на грань на ярус. Надішліть нам проєкт — підготуємо точний розрахунок і комерційну пропозицію."]], [["p", "Rebar spacers are cheap, but running out on site is expensive: the crew waits, the cage goes onto bricks and cover is lost. Too many is wasted money and leftover stock. It pays to calculate spacers in advance, together with the rebar and concrete estimate."], ["p", "This article gives a simple method for different elements and a worked example for a private house. Spacer types for each element are covered in <a href=\"/en/blog/how-to-choose-rebar-spacer\" data-go=\"post\" data-a=\"1\">“How to choose a rebar spacer”</a>."], ["h2", "What the quantity depends on"], ["ul", "<li><b>Element type:</b> slabs, foundations, walls, columns, beams.</li><li><b>Bar diameter and spacing:</b> thin bars sag between supports and need closer spacing.</li><li><b>Site loads:</b> foot traffic, barrows, the pump hose.</li><li><b>Base:</b> loose bases need more supports.</li><li><b>Geometry:</b> corners, openings, laps and extra-reinforcement zones need extra spacers.</li>"], ["h2", "Basic consumption rates"], ["p", "These practical guide values are what most builders use:"], ["ul", "<li>floor slabs and raft foundations (bottom mesh) — 4–6 pcs per m²;</li><li>walls and piers — 1–2 pcs per m² per face;</li><li>columns — 3–4 spacers per face for every 3 m of height;</li><li>beams — a chair every 0.8–1 m plus side “Zirochka” spacers.</li>"], ["blockquote", "<p>A per-m² rate is an average. Always adjust the final number for bar diameter and geometry.</p>"], ["h2", "Formulas"], ["h3", "Slabs and foundations"], ["p", "Quantity = slab area (m²) × rate (pcs/m²) × 1.1"], ["p", "The 1.1 factor is a 10 % reserve for losses, trimming and extra supports at openings."], ["h3", "Walls"], ["p", "Quantity = wall area (m²) × 2 faces × rate (pcs/m²) × 1.1"], ["h3", "Columns"], ["p", "Quantity = faces × levels over height × number of columns × 1.1"], ["h3", "From a given spacing"], ["p", "If the design specifies spacing, calculate more precisely: quantity = (length / spacing + 1) × (width / spacing + 1)."], ["h2", "Worked example: a private house"], ["p", "A house with a 12×10 m raft, cast basement walls and a floor slab:"], ["ol", "<li><b>Raft 120 m²</b> at 5 pcs/m²: 120 × 5 × 1.1 = 660 <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a> spacers.</li><li><b>Basement walls:</b> 44 m perimeter, 2.7 m high — 119 m². Two faces at 1.5 pcs/m²: 119 × 2 × 1.5 × 1.1 ≈ 393 <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka”</a> spacers.</li><li><b>Floor slab 110 m²</b> at 5 pcs/m²: 110 × 5 × 1.1 = 605 <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> chairs.</li><li><b>Slab edges:</b> 44 m perimeter each for raft and slab at 1 m spacing — about 90 “Zirochka”.</li>"], ["p", "Total: 660 “Nastil”, 605 “Stiika” and about 480 “Zirochka”. Spacers ship in packs, so round up to whole packs — pack sizes are on each product page."], ["cta", "{\"t\": \"We will calculate spacers from your design\", \"d\": \"Send a drawing or schedule — we will prepare an exact list by type and size, with prices and delivery.\", \"b\": [[\"Spacer catalog\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "Formwork accessories"], ["p", "If walls are cast in panel formwork with tie rods, calculate separately:"], ["ul", "<li><a href=\"/en/spacer-tube\" data-go=\"product\" data-a=\"9-0\">spacer tube</a> — in metres: tie points × wall thickness;</li><li><a href=\"/en/cone-spacer-konus\" data-go=\"product\" data-a=\"6-0\">cones</a> — two per tie point;</li><li><a href=\"/en/formwork-plug-korok\" data-go=\"product\" data-a=\"8-0\">plugs</a> — two per tie point, plus <a href=\"/en/fir-tree-plug\" data-go=\"product\" data-a=\"7-0\">fir-tree plugs</a> for unused panel holes.</li>"], ["p", "How each part works is explained in <a href=\"/en/blog/formwork-plugs-and-cones\" data-go=\"post\" data-a=\"5\">“Formwork cones, plugs and spacer tubes”</a>."], ["h2", "Common mistakes"], ["ul", "<li>Counting only slab areas and forgetting walls, columns and edges.</li><li>No reserve — and buying more spacers mid-job.</li><li>One height for the whole project, although foundation and slab cover differ.</li><li>Forgetting that formwork tube is sold by the metre, not by the piece.</li>"], ["h2", "FAQ"], ["h3", "Can spacers be calculated without drawings?"], ["p", "Roughly, yes — from slab and wall areas using the rates above. An exact size-by-size list needs drawings."], ["h3", "How many spacers per m² of slab?"], ["p", "On average 4–6 pcs for the bottom mesh — fewer for heavy bars, more for thin ones."], ["h3", "Can you do the calculation for us?"], ["p", "Yes. Send drawings or a bill of quantities and a manager will prepare a list of spacer types, sizes and quantities."], ["h2", "Conclusion"], ["p", "Spacer quantity is calculated from element areas and consumption rates, adjusted for bar diameter with a 10 % reserve: 4–6 pcs/m² for slabs, 1–2 pcs/m² per face for walls, 3–4 per face per level for columns. Send us your design for an exact calculation and quote."]]]}, {"id": 10, "st": "pub", "img": "/assets/img/blog/plastykovi-fiksatory.webp", "tag": ["Поради", "Guides"], "date": "2025-09-16", "slug": {"uk": "plastykovi-fiksatory-chy-tsehla", "en": "plastic-spacers-vs-bricks-metal-chairs"}, "t": ["Пластикові фіксатори, цегла чи металеві підставки: що надійніше і що дешевше", "Plastic spacers, bricks or metal chairs: which is more reliable and which is cheaper"], "e": ["Порівнюємо пластикові фіксатори арматури з уламками цегли, бетонними прокладками, брусками й металевими підставками: точність, довговічність, вплив на корозію, швидкість монтажу та реальну вартість.", "We compare plastic rebar spacers with brick fragments, concrete blocks, timber and metal chairs: accuracy, durability, corrosion risk, installation speed and real cost."], "b": [[["p", "На багатьох будмайданчиках досі можна побачити арматурний каркас, покладений на уламки цегли, обрізки брусків чи металеві «стільчики» з арматури. Аргумент завжди однаковий: «так дешевше» і «завжди так робили». Але чи справді це економія, і що відбувається з такою конструкцією через 10–20 років?"], ["p", "У цій статті чесно порівнюємо пластикові фіксатори арматури з популярними замінниками за точністю, довговічністю, впливом на корозію, швидкістю роботи й реальною вартістю."], ["h2", "Чому взагалі потрібні опори під арматуру"], ["p", "Будь-яка опора під арматурою має одне завдання — забезпечити проєктний захисний шар бетону й утримати каркас на місці під час робіт. Від захисного шару залежить, скільки часу бетон захищатиме сталь від вологи й корозії. Детально про це — в статті <a href=\"/blog/zakhysnyi-shar-betonu\" data-go=\"post\" data-a=\"2\">«Захисний шар бетону»</a>."], ["h2", "Варіант 1. Уламки цегли й каміння"], ["p", "<b>Плюси:</b> «безкоштовно», бо є на майданчику."], ["p", "<b>Мінуси:</b>"], ["ul", "<li>довільна висота — шар у кожній точці різний;</li><li>цегла вбирає воду й може стати каналом для вологи до арматури;</li><li>уламки колються під вагою каркаса й від вібрації;</li><li>погане зчеплення з бетоном і можливі порожнини навколо.</li>"], ["h2", "Варіант 2. Дерев’яні бруски"], ["p", "<b>Плюси:</b> легко підрізати під потрібну висоту."], ["p", "<b>Мінуси:</b> дерево вбирає воду, набухає, з часом гниє й залишає в бетоні порожнину — прямий шлях для вологи до арматури. Використовувати дерево як опору, що залишається в бетоні, неприпустимо."], ["h2", "Варіант 3. Металеві підставки з арматури"], ["p", "<b>Плюси:</b> міцні й витримують велике навантаження."], ["p", "<b>Мінуси:</b> метал, що торкається опалубки чи основи, стає «містком» корозії — іржа починається з поверхні й іде вглиб по підставці до каркаса. На стелі після розпалублення такі місця часто проступають рудими плямами. Крім того, їх треба виготовляти вручну, а це час бригади."], ["h2", "Варіант 4. Бетонні прокладки"], ["p", "<b>Плюси:</b> той самий матеріал, що й конструкція, добре працюють під великими навантаженнями."], ["p", "<b>Мінуси:</b> важкі, крихкі, виготовлення потребує часу, а точність висоти залежить від якості виготовлення."], ["h2", "Варіант 5. Пластикові фіксатори"], ["p", "<b>Плюси:</b>"], ["ul", "<li>точна висота, задана пресформою, — однаковий шар по всій конструкції;</li><li>не вбирають воду й не іржавіють — не створюють шляху для корозії;</li><li>ажурна форма дозволяє бетону щільно обтікати фіксатор;</li><li>різні моделі під різні задачі: <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a> для сипкої основи, <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійка»</a> для опалубки, <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочка»</a> для стін і колон;</li><li>монтаж займає секунди, без в’язального дроту.</li>"], ["p", "<b>Мінуси:</b> потрібно заздалегідь купити й привезти на об’єкт потрібні розміри."], ["blockquote", "<p>Найдешевша опора — та, за яку не доведеться платити ремонтом. Відновлення захисного шару на готовій конструкції коштує в рази більше, ніж усі фіксатори об’єкта.</p>"], ["h2", "Порівняння вартості: що насправді дешевше"], ["p", "Пластиковий фіксатор коштує кілька гривень. На плиту площею 100 м² потрібно 400–600 штук — це незначна частка вартості бетонних робіт. Натомість «безкоштовні» замінники мають приховані витрати:"], ["ul", "<li>час бригади на підбір, підрізку й укладання цегли чи брусків;</li><li>ризик не пройти приймання робіт технагляду;</li><li>ремонт захисного шару, якщо після розпалублення арматура проступила на поверхні;</li><li>скорочення терміну служби конструкції.</li>"], ["cta", "{\"t\": \"Перейдіть на заводські фіксатори\", \"d\": \"Підберемо фіксатори під ваш об’єкт і порахуємо, скільки їх потрібно — з цінами виробника.\", \"b\": [[\"Фіксатори арматури\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Коли все ж потрібні інші рішення"], ["p", "Пластикові фіксатори захисного шару тримають нижню арматуру й бічні грані. Для верхньої сітки плит і для дуже масивних каркасів використовують спеціальні підставки, розраховані на висоту між сітками. Це не замінник фіксаторів, а окремий елемент армування, який визначає проєкт."], ["h2", "Часті питання"], ["h3", "Чи витримують пластикові фіксатори вагу масивного каркаса?"], ["p", "Так, якщо підібрано правильну модель і крок установки. Для великих навантажень і діаметрів є «Засувка» — для стрижнів до 24 мм."], ["h3", "Чи не стане пластик слабким місцем у бетоні?"], ["p", "Ні. Переріз фіксатора дуже малий порівняно з конструкцією, а ажурна форма дає бетону заповнити простір навколо."], ["h3", "Чи приймає технагляд опори з цегли?"], ["p", "Технагляд перевіряє проєктний захисний шар. Довільні опори часто не дають його витримати, тож ризик зауважень значно вищий."], ["h2", "Висновок"], ["p", "Цегла, дерево й саморобні металеві підставки здаються безкоштовними, але дають довільний захисний шар і створюють шляхи для вологи й корозії. Пластикові фіксатори забезпечують точну висоту, не іржавіють і ставляться за секунди, а їхня вартість — незначна частка кошторису. Залиште заявку — підберемо фіксатори й підготуємо розрахунок."]], [["p", "On many sites you still see rebar cages resting on brick fragments, timber offcuts or home-made metal chairs. The argument is always the same: “it’s cheaper” and “we’ve always done it this way”. But is it really a saving, and what happens to such an element in 10–20 years?"], ["p", "This article honestly compares plastic rebar spacers with popular substitutes on accuracy, durability, corrosion, speed and real cost."], ["h2", "Why rebar needs supports at all"], ["p", "Any support under rebar has one job: provide the design concrete cover and hold the cage during works. Cover determines how long concrete protects steel from moisture and corrosion — see <a href=\"/en/blog/concrete-cover\" data-go=\"post\" data-a=\"2\">“Concrete cover”</a> for details."], ["h2", "Option 1. Brick fragments and stones"], ["p", "<b>Pros:</b> “free”, because they are already on site."], ["p", "<b>Cons:</b>"], ["ul", "<li>random height — cover differs at every point;</li><li>brick absorbs water and can become a moisture path to the rebar;</li><li>fragments crack under the cage and from vibration;</li><li>poor bond with concrete and possible voids around them.</li>"], ["h2", "Option 2. Timber offcuts"], ["p", "<b>Pros:</b> easy to cut to height."], ["p", "<b>Cons:</b> timber absorbs water, swells, rots over time and leaves a void in the concrete — a direct moisture path to the rebar. Timber must never be left in concrete as a support."], ["h2", "Option 3. Metal chairs made from rebar"], ["p", "<b>Pros:</b> strong, carry heavy loads."], ["p", "<b>Cons:</b> metal touching formwork or the base becomes a corrosion bridge — rust starts at the surface and travels along the chair into the cage. On ceilings these spots often show as rust stains after stripping. They are also made by hand, which costs crew time."], ["h2", "Option 4. Concrete blocks"], ["p", "<b>Pros:</b> the same material as the element; good under heavy loads."], ["p", "<b>Cons:</b> heavy, brittle, time-consuming to make, and height accuracy depends on how well they are made."], ["h2", "Option 5. Plastic spacers"], ["p", "<b>Pros:</b>"], ["ul", "<li>exact height set by the mold — equal cover across the element;</li><li>do not absorb water or rust — no corrosion path;</li><li>open shape lets concrete flow tightly around the spacer;</li><li>models for every task: <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a> for loose bases, <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> for formwork, <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka”</a> for walls and columns;</li><li>installed in seconds, without tie wire.</li>"], ["p", "<b>Cons:</b> you need to buy and deliver the right sizes in advance."], ["blockquote", "<p>The cheapest support is the one you never pay to repair. Restoring cover on a finished element costs many times more than all the spacers on the project.</p>"], ["h2", "Cost comparison: what is really cheaper"], ["p", "A plastic spacer costs a few hryvnias. A 100 m² slab needs 400–600 of them — a tiny share of the concrete works budget. “Free” substitutes carry hidden costs:"], ["ul", "<li>crew time to find, cut and place bricks or timber;</li><li>the risk of failing technical supervision;</li><li>cover repairs if rebar shows on the surface after stripping;</li><li>a shorter service life of the structure.</li>"], ["cta", "{\"t\": \"Switch to factory-made spacers\", \"d\": \"We will pick spacers for your project and calculate how many you need — at manufacturer prices.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "When other solutions are needed"], ["p", "Plastic cover spacers carry the bottom rebar and side faces. The top mesh of slabs and very massive cages use special chairs sized to the distance between meshes. These are not substitutes for spacers but a separate reinforcement element set by the design."], ["h2", "FAQ"], ["h3", "Can plastic spacers carry a heavy cage?"], ["p", "Yes, with the right model and spacing. For heavy loads and diameters there is “Zasuvka” — for bars up to 24 mm."], ["h3", "Will plastic become a weak point in concrete?"], ["p", "No. Its cross-section is tiny compared with the element, and its open shape lets concrete fill the space around it."], ["h3", "Will supervision accept brick supports?"], ["p", "Supervisors check the design cover. Random supports often fail to achieve it, so the risk of remarks is much higher."], ["h2", "Conclusion"], ["p", "Bricks, timber and home-made metal chairs look free but give random cover and create moisture and corrosion paths. Plastic spacers give an exact height, do not rust and install in seconds, at a tiny share of the budget. Leave a request and we will pick spacers and prepare a quote."]]]}, {"id": 11, "st": "pub", "img": "/assets/img/blog/kontraktne-lyttia-plastyku.webp", "tag": ["Виробництво", "Production"], "date": "2026-03-10", "slug": {"uk": "kontraktne-lyttia-plastyku", "en": "contract-injection-molding-ukraine"}, "t": ["Контрактне лиття пластику в Україні: як обрати виробника і не переплатити", "Contract plastic injection molding in Ukraine: how to choose a manufacturer and not overpay"], "e": ["На що звернути увагу, обираючи виробника для лиття пластикових виробів на замовлення: обладнання, пресформи, матеріали, контроль якості, терміни та прихована вартість.", "What to check when choosing a contract manufacturer for custom plastic parts: equipment, molds, materials, quality control, lead times and hidden costs."], "b": [[["p", "Контрактне лиття пластику — це коли ви розробили виріб, а виготовлення доручаєте виробнику з власними термопластавтоматами. Так працюють і стартапи з першим продуктом, і великі компанії, яким невигідно тримати власний цех. Але від вибору виробника залежить усе: якість деталей, стабільність поставок, ціна партії і навіть те, чи залишиться у вас пресформа."], ["p", "У цій статті розповідаємо, як обрати виробника для лиття пластмас під тиском, які питання поставити на старті і де найчастіше ховається переплата. Як влаштований сам процес лиття, ми описали в статті <a href=\"/blog/lyttia-pid-tyskom\" data-go=\"post\" data-a=\"3\">«Лиття пластмас під тиском»</a>."], ["h2", "Що таке контрактне лиття і кому воно потрібне"], ["p", "Контрактний виробник бере на себе виготовлення пластикових виробів за вашими кресленнями: від підбору матеріалу й пресформи до серійних партій, пакування та доставки. Замовник зосереджується на розробці, продажах і логістиці, а не на обладнанні й технологах."], ["p", "Такий формат підходить, якщо:"], ["ul", "<li>у вас новий виріб і немає власного виробництва;</li><li>обсяги не виправдовують купівлю термопластавтоматів;</li><li>потрібно швидко запустити серію без капіталовкладень;</li><li>треба розвантажити власний цех у пікові сезони.</li>"], ["h2", "На що звернути увагу при виборі виробника"], ["h3", "Обладнання"], ["p", "Запитайте, на яких машинах відливатимуть ваш виріб: зусилля змикання, об’єм упорскування, вік обладнання. Від цього залежить, чи підходить виробник для ваших розмірів і маси деталі та наскільки стабільним буде процес."], ["h3", "Пресформи: виготовлення і власність"], ["p", "Уточніть, чи виробник проєктує й виготовляє пресформи сам, хто є власником форми після оплати і чи можна її забрати. Чесна модель — пресформа, оплачена замовником, належить замовнику. Про те, що впливає на вартість форми, ми розповідали в статті <a href=\"/blog/presforma-pid-vash-vyrib\" data-go=\"post\" data-a=\"4\">«Пресформа на замовлення»</a>, а про послугу — на сторінці <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">«Виготовлення пресформ»</a>."], ["h3", "Матеріали"], ["p", "Хороший виробник допомагає підібрати пластик під умови роботи виробу — PP, PE, ABS, поліамід тощо — і пояснює, як вибір матеріалу вплине на ціну та довговічність."], ["h3", "Контроль якості"], ["p", "Запитайте, як погоджуються зразки, як контролюються розміри під час серії і що відбувається з бракованими виробами."], ["h3", "Терміни й логістика"], ["p", "Важливі не лише терміни першої партії, а й стабільність наступних. Уточніть, чи є склад готової продукції й доставка по Україні."], ["blockquote", "<p>Найдешевша ціна за деталь не завжди означає найдешевший проєкт. Переплата часто ховається в пресформі, браку й зірваних термінах.</p>"], ["h2", "Де ховається переплата"], ["ul", "<li><b>Дешева пресформа з малим ресурсом</b> — доводиться ремонтувати або виготовляти нову вже на другому тиражі.</li><li><b>Неоптимальна кількість гнізд</b> — або переплата за форму, або висока ціна деталі.</li><li><b>Відсутність аналізу технологічності</b> — дефекти й доопрацювання форми після запуску.</li><li><b>Пресформа, яку не можна забрати</b> — ви прив’язані до одного виробника.</li><li><b>Нестабільна якість партій</b> — витрати на сортування й повернення.</li>"], ["cta", "{\"t\": \"Запустимо ваш виріб у виробництво\", \"d\": \"Повний цикл у Львові: аналіз креслення, пресформа, пробне лиття, серійні партії й доставка.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Як проходить співпраця з PLASTIZA"], ["ol", "<li>Ви надсилаєте креслення, 3D-модель або зразок.</li><li>Ми аналізуємо технологічність, пропонуємо матеріал і готуємо комерційну пропозицію з вартістю пресформи та лиття.</li><li>Проєктуємо й виготовляємо пресформу або перевіряємо вашу.</li><li>Робимо пробне лиття й погоджуємо зразки.</li><li>Запускаємо серію, пакуємо й доставляємо по Україні.</li>"], ["p", "Наше виробництво у Львові — це власні термопластавтомати й досвід серійного випуску будівельних фіксаторів. Детальніше — на сторінці <a href=\"/vyrobnytstvo\" data-go=\"about\">«Виробництво»</a>."], ["h2", "Часті питання"], ["h3", "Який мінімальний тираж для контрактного лиття?"], ["p", "Залежить від виробу й пресформи. Лиття під тиском найвигідніше від кількох тисяч деталей, але можна почати з пробної партії."], ["h3", "Чи можна перенести виробництво з іншого заводу?"], ["p", "Так. Ми перевіримо вашу пресформу, підберемо обладнання й режими та виготовимо пробну партію."], ["h3", "Скільки часу займає запуск нового виробу?"], ["p", "Найдовший етап — виготовлення пресформи. Після неї пробне лиття й погодження займають від кількох днів."], ["h2", "Висновок"], ["p", "Обираючи виробника для контрактного лиття пластику, дивіться не лише на ціну деталі, а й на обладнання, власність і ресурс пресформи, контроль якості та стабільність поставок. Надішліть нам креслення чи зразок — підготуємо розрахунок вартості й термінів."]], [["p", "Contract plastic molding means you design the part and a manufacturer with its own injection molding machines produces it. Start-ups with a first product work this way, and so do large companies that do not want to run their own shop. But the choice of manufacturer decides everything: part quality, supply stability, batch price and even whether you keep your mold."], ["p", "This article explains how to choose an injection molding manufacturer, which questions to ask up front and where overpayment usually hides. How the process itself works is covered in <a href=\"/en/blog/injection-molding-process\" data-go=\"post\" data-a=\"3\">“Plastic injection molding”</a>."], ["h2", "What contract molding is and who needs it"], ["p", "A contract manufacturer produces plastic parts to your drawings — from material and mold selection to series batches, packing and delivery. You focus on design, sales and logistics, not on machines and process engineers."], ["p", "This model suits you if:"], ["ul", "<li>you have a new product and no production of your own;</li><li>volumes do not justify buying injection molding machines;</li><li>you need to launch a series quickly without capital investment;</li><li>your own shop needs relief in peak seasons.</li>"], ["h2", "What to check when choosing a manufacturer"], ["h3", "Equipment"], ["p", "Ask which machines will mold your part: clamping force, shot volume, machine age. This determines whether the manufacturer can handle your part size and weight and how stable the process will be."], ["h3", "Molds: making and ownership"], ["p", "Check whether the manufacturer designs and builds molds in-house, who owns the mold once paid for and whether you can take it away. The fair model: a mold paid for by the client belongs to the client. What drives mold cost is covered in <a href=\"/en/blog/custom-mold-checklist\" data-go=\"post\" data-a=\"4\">“Custom mold”</a>, and the service on <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">Mold making</a>."], ["h3", "Materials"], ["p", "A good manufacturer helps choose the plastic for the part’s operating conditions — PP, PE, ABS, polyamide and others — and explains how the choice affects price and durability."], ["h3", "Quality control"], ["p", "Ask how samples are approved, how dimensions are controlled during the run and what happens to rejects."], ["h3", "Lead times and logistics"], ["p", "Not only the first batch date matters but the stability of the following ones. Check whether there is a finished-goods warehouse and delivery across Ukraine."], ["blockquote", "<p>The lowest price per part is not always the cheapest project. Overpayment often hides in the mold, rejects and missed deadlines.</p>"], ["h2", "Where overpayment hides"], ["ul", "<li><b>A cheap mold with short tool life</b> — it needs repair or replacement by the second run.</li><li><b>The wrong number of cavities</b> — either overpaying for the mold or a high part price.</li><li><b>No manufacturability review</b> — defects and mold rework after launch.</li><li><b>A mold you cannot take away</b> — you are tied to one manufacturer.</li><li><b>Unstable batch quality</b> — sorting and return costs.</li>"], ["cta", "{\"t\": \"We will put your part into production\", \"d\": \"Full cycle in Lviv: drawing review, mold, trial shots, series batches and delivery.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "How working with PLASTIZA goes"], ["ol", "<li>You send a drawing, 3D model or sample.</li><li>We review manufacturability, suggest a material and prepare a quote for the mold and molding.</li><li>We design and build the mold, or check yours.</li><li>We run trial shots and approve samples.</li><li>We start the series, pack and deliver across Ukraine.</li>"], ["p", "Our Lviv plant has its own injection molding machines and experience in series production of construction spacers. More on <a href=\"/en/production\" data-go=\"about\">Production</a>."], ["h2", "FAQ"], ["h3", "What is the minimum run for contract molding?"], ["p", "It depends on the part and mold. Injection molding pays off from several thousand parts, but you can start with a trial batch."], ["h3", "Can production be transferred from another plant?"], ["p", "Yes. We check your mold, choose the machine and settings and produce a trial batch."], ["h3", "How long does a new part take to launch?"], ["p", "Mold making is the longest stage. After it, trials and approval take from a few days."], ["h2", "Conclusion"], ["p", "When choosing a contract molding manufacturer, look beyond the part price: equipment, mold ownership and tool life, quality control and supply stability. Send us a drawing or sample for a price and lead-time estimate."]]]}];
export const BLOG4_DATES = {"2": "2025-02-11", "1": "2025-03-18", "3": "2025-04-22", "4": "2025-05-27", "5": "2025-07-01"};
